16	// Table ...
17	type Table struct {
18		Node
19	
20		Columns        []Column
21		columnIndexes  map[string]int
22		columnPosition *ast.ColumnPosition
23	
24		Indexes      []Index
25		indexIndexes map[string]int
26	
27		ForeignKeys      []ForeignKey
28		indexForeignKeys map[string]int
29	}
30	
31	// NewTable ...
32	func NewTable(name string) *Table {
33		return NewTableWithAction(name, MigrateAddAction)
34	}
35	
36	// NewTableWithAction ...
37	func NewTableWithAction(name string, action MigrateAction) *Table {
38		return &Table{
39			Node: Node{
40				Name:   name,
41				Action: action,
42			},
43			Columns:          []Column{},
44			columnIndexes:    map[string]int{},
45			Indexes:          []Index{},
46			indexIndexes:     map[string]int{},
47			ForeignKeys:      []ForeignKey{},
48			indexForeignKeys: map[string]int{},
49		}
50	}
51	
52	// AddColumn ...
53	func (t *Table) AddColumn(col Column) {
54		id := t.getIndexColumn(col.Name)
55		switch {
56		case id == -1:
57			t.Columns = append(t.Columns, col)
58			t.columnIndexes[col.Name] = len(t.Columns) - 1
59			id = len(t.Columns) - 1
60	
61		case t.Columns[id].Action != MigrateAddAction:
62			t.Columns[id] = col
63	
64		default:
65			t.Columns[id].CurrentAttr.Options = append(t.Columns[id].CurrentAttr.Options, col.CurrentAttr.Options...)
66	
67			if size := len(t.Columns[id].CurrentAttr.Options); size > 0 {
68				for i := range t.Columns[id].CurrentAttr.Options[:size-1] {
69					if t.Columns[id].CurrentAttr.Options[i].Tp == ast.ColumnOptionPrimaryKey {
70						t.Columns[id].CurrentAttr.Options[i], t.Columns[id].CurrentAttr.Options[size-1] = t.Columns[id].CurrentAttr.Options[size-1], t.Columns[id].CurrentAttr.Options[i]
71						break
72					}
73				}
74			}
75	
76			t.Columns[id].CurrentAttr.MysqlType = col.CurrentAttr.MysqlType
77			return
78		}
79	
80		if t.columnPosition != nil {
81			defer func() {
82				t.columnPosition = nil
83			}()
84	
85			switch t.columnPosition.Tp {
86			case ast.ColumnPositionFirst:
87				t.swapOrder(col.Name, id, 0)
88	
89			case ast.ColumnPositionAfter:
90				if afterID := t.getIndexColumn(t.columnPosition.RelativeColumn.Name.O); afterID >= 0 {
91					t.swapOrder(col.Name, id, afterID+1)
92				}
93			}
94		}
95	}
96	
97	func (t *Table) swapOrder(colName string, oldID, newID int) {
98		if oldID == newID {
99			return
100		}
101	
102		if newID == len(t.Columns)-1 {
103			t.Columns = append(t.Columns, t.Columns[oldID])
104		} else {
105			oldCol := t.Columns[oldID]
106			t.Columns = append(t.Columns[:newID+1], t.Columns[newID:]...)
107			t.Columns[newID] = oldCol
108		}
109	
110		switch {
111		case oldID > newID:
112			for k := range t.columnIndexes {
113				if t.columnIndexes[k] >= newID && t.columnIndexes[k] < oldID {
114					t.columnIndexes[k]++
115				}
116			}
117	
118			if oldID == len(t.Columns)-2 {
119				t.Columns = t.Columns[:len(t.Columns)-1]
120			} else {
121				t.Columns = append(t.Columns[:oldID], t.Columns[oldID+1:]...)
122			}
123	
124		case oldID < newID:
125			for k := range t.columnIndexes {
126				if t.columnIndexes[k] > oldID && t.columnIndexes[k] <= newID {
127					t.columnIndexes[k]--
128				}
129			}
130	
131			t.Columns = append(t.Columns[:oldID-1], t.Columns[oldID:]...)
132		}
133	
134		t.columnIndexes[colName] = newID
135	}
136	
137	func (t *Table) removeColumn(colName string) {
138		id := t.getIndexColumn(colName)
139		switch {
140		case id == -1:
141			col := Column{Node: Node{Name: colName, Action: MigrateRemoveAction}}
142			t.Columns = append(t.Columns, col)
143			t.columnIndexes[colName] = len(t.Columns) - 1
144	
145		case t.Columns[id].Action == MigrateAddAction:
146			t.Columns[id].Action = MigrateNoAction
147	
148		default:
149			t.Columns[id].Action = MigrateRemoveAction
150		}
151	}
152	
153	// RenameColumn ...
154	func (t *Table) RenameColumn(oldName, newName string) {
155		if id := t.getIndexColumn(oldName); id >= 0 {
156			t.Columns[id].Action = MigrateRenameAction
157			t.Columns[id].OldName = oldName
158			t.Columns[id].Name = newName
159			t.columnIndexes[newName] = id
160			delete(t.columnIndexes, oldName)
161		}
162	}
163	
164	// AddIndex ...
165	func (t *Table) AddIndex(idx Index) {
166		id := t.getIndexIndex(idx.Name)
167		if id == -1 {
168			t.Indexes = append(t.Indexes, idx)
169			t.indexIndexes[idx.Name] = len(t.Indexes) - 1
170			return
171		}
172	
173		t.Indexes[id] = idx
174	}
175	
176	// RemoveIndex ...
177	func (t *Table) RemoveIndex(idxName string) {
178		id := t.getIndexIndex(idxName)
179		if id == -1 {
180			idx := Index{Node: Node{Name: idxName, Action: MigrateRemoveAction}}
181			t.Indexes = append(t.Indexes, idx)
182			t.indexIndexes[idxName] = len(t.Indexes) - 1
183			return
184		}
185	
186		if t.Indexes[id].Action == MigrateAddAction {
187			t.Indexes[id].Action = MigrateNoAction
188		} else {
189			t.Indexes[id].Action = MigrateRemoveAction
190		}
191	}
192	
193	// RenameIndex ...
194	func (t *Table) RenameIndex(oldName, newName string) {
195		if id := t.getIndexIndex(oldName); id >= 0 {
196			t.Indexes[id].Action = MigrateRenameAction
197			t.Indexes[id].OldName = oldName
198			t.Indexes[id].Name = newName
199			t.indexIndexes[newName] = id
200			delete(t.indexIndexes, oldName)
201		}
202	}
203	
204	// AddForeignKey ...
205	func (t *Table) AddForeignKey(fk ForeignKey) {
206		id := t.getIndexForeignKey(fk.Name)
207		if id == -1 {
208			t.ForeignKeys = append(t.ForeignKeys, fk)
209			t.indexForeignKeys[fk.Name] = len(t.ForeignKeys) - 1
210		} else {
211			t.ForeignKeys[id] = fk
212		}
213	
214		for i := range t.Columns {
215			if t.Columns[i].Name == fk.Column {
216				t.Columns[i].CurrentAttr.Options = append(t.Columns[i].CurrentAttr.Options, &ast.ColumnOption{
217					Tp: ast.ColumnOptionReference,
218				})
219			}
220		}
221	}
222	
223	// RemoveForeignKey ...
224	func (t *Table) RemoveForeignKey(fkName string) {
225		id := t.getIndexForeignKey(fkName)
226		if id == -1 {
227			fk := ForeignKey{Node: Node{Name: fkName, Action: MigrateRemoveAction}}
228			t.ForeignKeys = append(t.ForeignKeys, fk)
229			t.indexForeignKeys[fkName] = len(t.ForeignKeys) - 1
230			return
231		}
232	
233		if t.ForeignKeys[id].Action == MigrateAddAction {
234			t.ForeignKeys[id].Action = MigrateNoAction
235		} else {
236			t.ForeignKeys[id].Action = MigrateRemoveAction
237		}
238	}
239	
240	func (t Table) getIndexColumn(colName string) int {
241		if v, ok := t.columnIndexes[colName]; ok {
242			return v
243		}
244	
245		return -1
246	}
247	
248	func (t Table) getIndexIndex(idxName string) int {
249		if v, ok := t.indexIndexes[idxName]; ok {
250			return v
251		}
252	
253		return -1
254	}
255	
256	func (t Table) getIndexForeignKey(fkName string) int {
257		if v, ok := t.indexForeignKeys[fkName]; ok {
258			return v
259		}
260	
261		return -1
262	}
263	
264	func hasChangedMysqlOptions(new, old []*ast.ColumnOption) bool {
265		optNew := make([]*ast.ColumnOption, 0, len(new))
266		hasComment := false
267		for _, v := range new {
268			if !hasComment {
269				optNew = append(optNew, v)
270			}
271			if v.Tp == ast.ColumnOptionComment {
272				hasComment = true
273			}
274		}
275	
276		optOld := make([]*ast.ColumnOption, 0, len(old))
277		hasComment = false
278		for _, v := range old {
279			if !hasComment {
280				optOld = append(optOld, v)
281			}
282			if v.Tp == ast.ColumnOptionComment {
283				hasComment = true
284			}
285		}
286	
287		if len(optNew) != len(optOld) {
288			return true
289		}
290	
291		mNew := map[ast.ColumnOptionType]int{}
292		for i := range optNew {
293			mNew[optNew[i].Tp] += 1
294		}
295	
296		mOld := map[ast.ColumnOptionType]int{}
297		for i := range optOld {
298			mOld[optOld[i].Tp] += 1
299		}
300	
301		for k, v := range mOld {
302			if mNew[k] != v {
303				return true
304			}
305		}
306	
307		return false
308	}
309	
310	func hasChangedMysqlType(new, old *types.FieldType) bool {
311		return new != nil && new.String() != old.String()
312	}
313	
314	func hasChangePostgresType(new, old *ptypes.T) bool {
315		return new != nil && new.SQLString() != old.SQLString()
316	}
317	
318	// Diff differ between 2 migrations
319	func (t *Table) Diff(old Table) {
320		for i := range t.Columns {
321			if j := old.getIndexColumn(t.Columns[i].Name); t.Columns[i].Action == MigrateAddAction &&
322				j >= 0 && old.Columns[j].Action != MigrateNoAction {
323				if hasChangedMysqlOptions(t.Columns[i].CurrentAttr.Options, old.Columns[j].CurrentAttr.Options) ||
324					hasChangedMysqlType(t.Columns[i].CurrentAttr.MysqlType, old.Columns[j].CurrentAttr.MysqlType) ||
325					hasChangePostgresType(t.Columns[i].CurrentAttr.PgType, old.Columns[j].CurrentAttr.PgType) {
326					t.Columns[i].Action = MigrateModifyAction
327					t.Columns[i].PreviousAttr = old.Columns[j].CurrentAttr
328				} else {
329					t.Columns[i].Action = MigrateNoAction
330				}
331			}
332		}
333	
334		for j := range old.Columns {
335			if old.Columns[j].Action == MigrateAddAction && t.getIndexColumn(old.Columns[j].Name) == -1 {
336				old.Columns[j].Action = MigrateRemoveAction
337				t.AddColumn(old.Columns[j])
338	
339				if j == 0 {
340					t.swapOrder(old.Columns[j].Name, len(t.Columns)-1, 0)
341				} else if newID, ok := old.columnIndexes[old.Columns[j-1].Name]; ok {
342					t.swapOrder(old.Columns[j].Name, len(t.Columns)-1, newID+1)
343				}
344			}
345		}
346	
347		for i := range t.Indexes {
348			if j := old.getIndexIndex(t.Indexes[i].Name); t.Indexes[i].Action == MigrateAddAction &&
349				j >= 0 && old.Indexes[j].Action != MigrateNoAction {
350				if t.Indexes[i].Typ == old.Indexes[j].Typ && utils.SlideStrEqual(t.Indexes[i].Columns, old.Indexes[j].Columns) {
351					t.Indexes[i].Action = MigrateNoAction
352				} else {
353					t.Indexes[i] = old.Indexes[j]
354					t.Indexes[i].Action = MigrateModifyAction
355				}
356			}
357		}
358	
359		for j := range old.Indexes {
360			if old.Indexes[j].Action == MigrateAddAction && t.getIndexIndex(old.Indexes[j].Name) == -1 {
361				old.Indexes[j].Action = MigrateRemoveAction
362				t.AddIndex(old.Indexes[j])
363			}
364		}
365	
366		for i := range t.ForeignKeys {
367			if j := old.getIndexForeignKey(t.ForeignKeys[i].Name); t.ForeignKeys[i].Action == MigrateAddAction &&
368				j >= 0 && old.ForeignKeys[j].Action != MigrateNoAction {
369				t.ForeignKeys[i] = old.ForeignKeys[j]
370				t.ForeignKeys[i].Action = MigrateModifyAction
371			}
372		}
373	
374		for j := range old.ForeignKeys {
375			if old.ForeignKeys[j].Action == MigrateAddAction && t.getIndexForeignKey(old.ForeignKeys[j].Name) == -1 {
376				old.ForeignKeys[j].Action = MigrateRemoveAction
377				t.AddForeignKey(old.ForeignKeys[j])
378			}
379		}
380	}
381	
382	type mOrder struct {
383		k string
384		v int
385	}
386	
387	// Arrange correct column order
388	func (t *Table) Arrange() {
389		orders := make([]mOrder, 0, len(t.columnIndexes))
390		for k, v := range t.columnIndexes {
391			orders = append(orders, mOrder{
392				k: k,
393				v: v,
394			})
395		}
396		sort.Slice(orders, func(i, j int) bool {
397			return orders[i].v < orders[j].v
398		})
399	
400		for i := range orders {
401			for j := range t.Columns {
402				if orders[i].k == t.Columns[j].Name {
403					t.Columns[i], t.Columns[j] = t.Columns[j], t.Columns[i]
404					break
405				}
406			}
407		}
408	}
409	
410	func (t Table) hashValue() string {
411		cols, idxs := make([]string, len(t.Columns)), make([]string, len(t.Indexes))
412		for i := range t.Columns {
413			cols[i] = t.Columns[i].hashValue()
414		}
415		sort.Slice(cols, func(i, j int) bool {
416			return cols[i] < cols[j]
417		})
418	
419		for i := range t.Indexes {
420			idxs[i] = t.Indexes[i].hashValue()
421		}
422		sort.Slice(idxs, func(i, j int) bool {
423			return idxs[i] < idxs[j]
424		})
425	
426		strHash := strings.Join(append(cols, idxs...), ";")
427		hash := md5.Sum([]byte(strHash))
428		return hex.EncodeToString(hash[:])
429	}
430	
431	// MigrationColumnUp ...
432	func (t Table) MigrationColumnUp() ([]string, map[string]struct{}) {
433		switch t.Action {
434		case MigrateNoAction:
435			strSqls := make([]string, 0)
436			dropCols := make(map[string]struct{})
437			for i := range t.Columns {
438				if t.Columns[i].Action != MigrateNoAction {
439					after := ""
440					if t.Columns[i].Action == MigrateAddAction {
441						for j := i - 1; j >= 0; j-- {
442							if t.Columns[j].Action != MigrateRemoveAction {
443								after = t.Columns[j].Name
444								break
445							}
446						}
447					} else if t.Columns[i].Action == MigrateRemoveAction {
448						dropCols[t.Columns[i].Name] = struct{}{}
449					}
450	
451					if ignoreFieldOrder || after == "" {
452						strSqls = append(strSqls, t.Columns[i].migrationUp(t.Name, "", -1)...)
453					} else {
454						strSqls = append(strSqls, t.Columns[i].migrationUp(t.Name, after, -1)...)
455					}
456				}
457			}
458	
459			return strSqls, dropCols
460	
461		case MigrateAddAction:
462			maxIdent := len(t.Columns[0].Name)
463			for i := range t.Columns {
464				if t.Columns[i].Action == MigrateAddAction || t.Columns[i].Action == MigrateModifyAction || t.Columns[i].Action == MigrateRenameAction {
465					if len(t.Columns[i].Name) > maxIdent {
466						maxIdent = len(t.Columns[i].Name)
467					}
468				}
469			}
470	
471			strCols := make([]string, 0)
472			commentCols := make([]string, 0)
473			for i := range t.Columns {
474				switch t.Columns[i].Action {
475				case MigrateAddAction:
476					strCols = append(strCols, " "+t.Columns[i].migrationUp("", "", maxIdent)[0])
477				case MigrateModifyAction, MigrateRenameAction:
478					nCol := t.Columns[i]
479					nCol.Action = MigrateAddAction
480					strCols = append(strCols, " "+nCol.migrationUp("", "", maxIdent)[0])
481				}
482	
483				commentCols = append(commentCols, t.Columns[i].migrationCommentUp(t.Name)...)
484			}
485	
486			return append([]string{fmt.Sprintf(sql.CreateTableStm(), sql.EscapeSqlName(t.Name), strings.Join(strCols, ",\n"), "")}, commentCols...), nil
487	
488		case MigrateRemoveAction:
489			return []string{fmt.Sprintf(sql.DropTableStm(), sql.EscapeSqlName(t.Name))}, nil
490	
491		case MigrateModifyAction:
492			return nil, nil
493	
494		default:
495			return nil, nil
496		}
497	}
498	
499	// MigrationIndexUp ...
500	func (t Table) MigrationIndexUp(dropCols map[string]struct{}) []string {
501		switch t.Action {
502		case MigrateNoAction:
503			strSqls := make([]string, 0)
504			for i := range t.Indexes {
505				if _, ok := dropCols[t.Indexes[i].Columns[0]]; t.Indexes[i].Action != MigrateNoAction &&
506					(t.Indexes[i].Action != MigrateRemoveAction || !ok) {
507					strSqls = append(strSqls, t.Indexes[i].migrationUp(t.Name)...)
508				}
509			}
510			return strSqls
511	
512		case MigrateAddAction:
513			strSqls := make([]string, 0)
514			for i := range t.Indexes {
515				if t.Indexes[i].Action == MigrateAddAction {
516					strSqls = append(strSqls, t.Indexes[i].migrationUp(t.Name)...)
517				}
518			}
519			return strSqls
520	
521		case MigrateRemoveAction:
522			return nil
523	
524		case MigrateModifyAction:
525			return nil
526	
527		default:
528			return nil
529		}
530	}
531	
532	// MigrationForeignKeyUp ...
533	func (t Table) MigrationForeignKeyUp(dropCols map[string]struct{}) []string {
534		switch t.Action {
535		case MigrateNoAction:
536			strSqls := make([]string, 0)
537			for i := range t.ForeignKeys {
538				if _, ok := dropCols[t.ForeignKeys[i].Column]; t.ForeignKeys[i].Action != MigrateNoAction &&
539					(t.ForeignKeys[i].Action != MigrateRemoveAction || !ok) {
540					strSqls = append(strSqls, t.ForeignKeys[i].migrationUp(t.Name)...)
541				}
542			}
543			return strSqls
544	
545		case MigrateAddAction:
546			strSqls := make([]string, 0)
547			for i := range t.ForeignKeys {
548				if t.ForeignKeys[i].Action == MigrateAddAction {
549					strSqls = append(strSqls, t.ForeignKeys[i].migrationUp(t.Name)...)
550				}
551			}
552			return strSqls
553	
554		case MigrateRemoveAction:
555			return nil
556	
557		case MigrateModifyAction:
558			return nil
559	
560		default:
561			return nil
562		}
563	}
564	
565	// MigrationColumnDown ...
566	func (t Table) MigrationColumnDown() ([]string, map[string]struct{}) {
567		switch t.Action {
568		case MigrateNoAction:
569			strSqls := make([]string, 0)
570			dropCols := make(map[string]struct{})
571			for i := range t.Columns {
572				if t.Columns[i].Action != MigrateNoAction {
573					after := ""
574					if t.Columns[i].Action == MigrateRemoveAction {
575						for j := i - 1; j >= 0; j-- {
576							if t.Columns[j].Action != MigrateAddAction {
577								after = t.Columns[j].Name
578								break
579							}
580						}
581					} else if t.Columns[i].Action == MigrateAddAction {
582						dropCols[t.Columns[i].Name] = struct{}{}
583					}
584	
585					if ignoreFieldOrder || after == "" {
586						strSqls = append(strSqls, t.Columns[i].migrationDown(t.Name, "")...)
587					} else {
588						strSqls = append(strSqls, t.Columns[i].migrationDown(t.Name, after)...)
589					}
590				}
591			}
592	
593			return strSqls, dropCols
594	
595		case MigrateAddAction:
596			t.Action = MigrateRemoveAction
597			return t.MigrationColumnUp()
598	
599		case MigrateRemoveAction:
600			t.Action = MigrateAddAction
601			return t.MigrationColumnUp()
602	
603		case MigrateModifyAction:
