9	// ParserMysql ...
10	func (p *Parser) ParserMysql(sql string) error {
11		ps := parser.New()
12		stmtNodes, _, err := ps.Parse(sql, "", "")
13		if err != nil {
14			return err
15		}
16	
17		for _, n := range stmtNodes {
18			switch n.(type) {
19			case ast.DDLNode:
20				n.Accept(p)
21			}
22		}
23	
24		return nil
25	}
26	
27	/*
28	Walk with statements:
29	
30	DropTableStmt
31	AlterTableStmt
32	DropIndexStmt
33	CreateTableStmt
34	CreateIndexStmt
35	*/
36	func (p *Parser) Enter(in ast.Node) (ast.Node, bool) {
37		// get Table name
38		if tb, ok := in.(*ast.TableName); ok {
39			p.Migration.Using(tb.Name.O)
40		}
41	
42		// drop Table
