1	package sqlparser
2	
3	import (
4		"strings"
5	
6		"github.com/auxten/postgresql-parser/pkg/sql/parser"
7		"github.com/auxten/postgresql-parser/pkg/sql/sem/tree"
8		"github.com/auxten/postgresql-parser/pkg/walk"
9		"github.com/pingcap/tidb/pkg/parser/ast"
10		"github.com/sunary/sqlize/element"
11	)
12	
13	// ParserPostgresql ...
14	func (p *Parser) ParserPostgresql(sql string) error {
15		w := &walk.AstWalker{
16			Fn: p.walker,
17		}
18	
19		stmts, err := parser.Parse(sql)
20		if err != nil {
21			return err
22		}
23	
24		_, err = w.Walk(stmts, nil)
25		return err
26	}
27	
28	/*
29	Walk with statements:
30	
31	CreateTable
32	ColumnTableDef
33	CreateIndex
34	DropIndex
35	AlterTable
36	RenameTable
37	*/
38	func (p *Parser) walker(ctx interface{}, node interface{}) (stop bool) {
39		switch n := node.(type) {
40		case *tree.CreateTable:
41			tbName := n.Table.Table()
42	
43			tb := element.NewTableWithAction(tbName, element.MigrateAddAction)
44			p.Migration.AddTable(*tb)
45			p.Migration.Using(tbName)
46	
47		case *tree.ColumnTableDef:
48			col, indexes := postgresColumn(n)
49			p.Migration.AddColumn("", col)
50			if len(indexes) > 0 {
51				for i := range indexes {
52					p.Migration.AddIndex("", indexes[i])
53				}
54			}
55	
56		case *tree.CommentOnColumn:
57			p.Migration.AddComment(n.TableName.String(), n.Column(), *n.Comment)
58	
59		case *tree.CreateIndex:
60			p.Migration.AddIndex("", postgresIndex(n))
61	
62		case *tree.DropIndex:
63			for i := range n.IndexList {
64				p.Migration.RemoveIndex("", n.IndexList[i].Index.String())
65			}
66	
67		case *tree.AlterTable:
68			switch nc := n.Cmds[0].(type) {
69			case *tree.AlterTableRenameTable:
70				p.Migration.RenameTable(n.Table.String(), nc.NewName.TableName.String())
71	
72			case *tree.AlterTableRenameColumn:
73				p.Migration.RenameColumn(n.Table.String(), nc.Column.String(), nc.NewName.String())
74	
75			case *tree.AlterTableRenameConstraint:
76				p.Migration.RenameIndex(n.Table.String(), nc.Constraint.String(), nc.NewName.String())
77	
78			case *tree.AlterTableAddColumn:
79				col, indexes := postgresColumn(nc.ColumnDef)
80				p.Migration.AddColumn(n.Table.String(), col)
81				if len(indexes) > 0 {
82					for i := range indexes {
83						p.Migration.AddIndex(n.Table.String(), indexes[i])
84					}
85				}
86	
87			case *tree.AlterTableDropColumn:
88				p.Migration.RemoveColumn(n.Table.String(), nc.Column.String())
89	
90			case *tree.AlterTableDropNotNull:
91				p.Migration.RemoveColumn(n.Table.String(), nc.Column.String())
92	
93			case *tree.AlterTableAlterColumnType:
94				col := element.Column{
95					Node: element.Node{Name: nc.Column.String(), Action: element.MigrateModifyAction},
96					CurrentAttr: element.SqlAttr{
97						PgType: nc.ToType,
98					},
99				}
100				p.Migration.AddColumn(n.Table.String(), col)
101	
102			case *tree.AlterTableSetDefault:
103				if nc.Default != nil {
104					col := element.Column{
105						Node: element.Node{Name: nc.Column.String(), Action: element.MigrateModifyAction},
106						CurrentAttr: element.SqlAttr{
107							Options: []*ast.ColumnOption{{
108								Expr:     nil,
109								Tp:       ast.ColumnOptionDefaultValue,
110								StrValue: nc.Default.String(),
111							}},
112						},
113					}
114					p.Migration.AddColumn(n.Table.String(), col)
115				}
116	
117			case *tree.AlterTableAddConstraint:
118				switch nc2 := nc.ConstraintDef.(type) {
119				case *tree.UniqueConstraintTableDef:
120					p.Migration.AddIndex(n.Table.String(), postgresUnique(nc2))
121	
122				case *tree.ForeignKeyConstraintTableDef:
123					p.Migration.AddForeignKey(n.Table.String(), postgresForeignKey(nc2))
124				}
125	
126			case *tree.AlterTableDropConstraint:
127				consName := nc.Constraint.String()
128				if strings.HasPrefix(strings.ToLower(consName), "fk") { // detect ForeignKey Constraint
129					p.Migration.RemoveForeignKey(n.Table.String(), consName)
130				} else {
131					p.Migration.RemoveIndex(n.Table.String(), consName)
132				}
133			}
134	
135		case *tree.RenameTable:
136			p.Migration.RenameTable(n.Name.String(), n.NewName.String())
137		}
138	
139		return false
140	}
141	
142	func postgresColumn(n *tree.ColumnTableDef) (element.Column, []element.Index) {
143		opts := make([]*ast.ColumnOption, 0, 1)
144		if n.DefaultExpr.Expr != nil {
145			opts = append(opts, &ast.ColumnOption{
146				Tp:       ast.ColumnOptionDefaultValue,
147				StrValue: n.DefaultExpr.Expr.String(),
148			})
149		}
150	
151		indexes := []element.Index{}
152		switch {
153		case n.PrimaryKey.IsPrimaryKey:
154			indexes = append(indexes, element.Index{
155				Node:    element.Node{Name: "primary_key", Action: element.MigrateAddAction},
156				Typ:     ast.IndexKeyTypeNone,
157				CnsTyp:  ast.ConstraintPrimaryKey,
158				Columns: []string{n.Name.String()},
159			})
160		case n.Unique:
161			indexes = append(indexes, element.Index{
162				Node: element.Node{
163					Name:   n.UniqueConstraintName.String(),
164					Action: element.MigrateAddAction,
165				},
166				Typ:     ast.IndexKeyTypeUnique,
167				Columns: []string{n.Name.String()},
168			})
169		case n.References.Table != nil:
170		}
171	
172		return element.Column{
173			Node: element.Node{Name: n.Name.String(), Action: element.MigrateAddAction},
174			CurrentAttr: element.SqlAttr{
175				PgType:  n.Type,
176				Options: opts,
177			},
178		}, indexes
179	}
180	
181	func postgresUnique(n *tree.UniqueConstraintTableDef) element.Index {
182		cols := make([]string, len(n.Columns))
183		for i := range n.Columns {
184			cols[i] = n.Columns[i].Column.String()
185		}
186	
187		if n.PrimaryKey {
188			return element.Index{
189				Node:    element.Node{Name: "primary_key", Action: element.MigrateAddAction},
190				Typ:     ast.IndexKeyTypeNone,
191				CnsTyp:  ast.ConstraintPrimaryKey,
192				Columns: cols,
193			}
194		}
195	
196		return element.Index{
197			Node: element.Node{
198				Name:   n.Name.String(),
