1	package element
2	
3	import (
4		"bytes"
5		"crypto/md5"
6		"encoding/hex"
7		"fmt"
8		"strconv"
9		"strings"
10	
11		ptypes "github.com/auxten/postgresql-parser/pkg/sql/types"
12		"github.com/pingcap/tidb/pkg/parser/ast"
13		"github.com/pingcap/tidb/pkg/parser/format"
14		"github.com/pingcap/tidb/pkg/parser/types"
15		sqlite "github.com/rqlite/sql"
16		"github.com/sunary/sqlize/sqltemplates"
17	)
18	
19	const (
20		// UppercaseRestoreFlag ...
21		UppercaseRestoreFlag = format.RestoreStringSingleQuotes | format.RestoreKeyWordUppercase | format.RestoreNameUppercase | format.RestoreNameBackQuotes
22		// LowerRestoreFlag ...
23		LowerRestoreFlag = format.RestoreStringSingleQuotes | format.RestoreKeyWordLowercase | format.RestoreNameLowercase | format.RestoreNameBackQuotes
24	)
25	
26	type SqlAttr struct {
27		MysqlType *types.FieldType
28		PgType    *ptypes.T
29		LiteType  *sqlite.Type
30		Options   []*ast.ColumnOption
31		Comment   string
32	}
33	
34	// Column ...
35	type Column struct {
36		Node
37	
38		CurrentAttr  SqlAttr
39		PreviousAttr SqlAttr
40	}
41	
42	// GetType ...
43	func (c Column) GetType() byte {
44		if c.CurrentAttr.MysqlType != nil {
45			return c.CurrentAttr.MysqlType.GetType()
46		}
47	
48		return 0
49	}
50	
51	// DataType ...
52	func (c Column) DataType() string {
53		return c.typeDefinition(false)
54	}
55	
56	// Constraint ...
57	func (c Column) Constraint() string {
58		for _, opt := range c.CurrentAttr.Options {
59			switch opt.Tp {
60			case ast.ColumnOptionPrimaryKey:
61				return "PK"
62			case ast.ColumnOptionReference:
63				return "FK"
64			}
65		}
66	
67		return ""
68	}
69	
70	// HasDefaultValue ...
71	func (c Column) HasDefaultValue() bool {
72		for _, opt := range c.CurrentAttr.Options {
73			if opt.Tp == ast.ColumnOptionDefaultValue {
74				return true
75			}
76		}
77	
78		return false
79	}
80	
81	func (c Column) hashValue() string {
82		strHash := sql.EscapeSqlName(c.Name)
83		strHash += " " + c.typeDefinition(false)
84		hash := md5.Sum([]byte(strHash))
85		return hex.EncodeToString(hash[:])
86	}
87	
88	func (c Column) migrationUp(tbName, after string, ident int) []string {
89		switch c.Action {
90		case MigrateNoAction:
91			return nil
92	
93		case MigrateAddAction:
94			strSql := sql.EscapeSqlName(c.Name)
95	
96			if ident > len(c.Name) {
97				strSql += strings.Repeat(" ", ident-len(c.Name))
98			}
99	
100			strSql += c.definition(false)
101	
102			if ident < 0 {
103				if after != "" {
104					return []string{fmt.Sprintf(sql.AlterTableAddColumnAfterStm(), sql.EscapeSqlName(tbName), strSql, sql.EscapeSqlName(after))}
105				}
106				return []string{fmt.Sprintf(sql.AlterTableAddColumnFirstStm(), sql.EscapeSqlName(tbName), strSql)}
107			}
108	
109			return append([]string{strSql}, c.migrationCommentUp(tbName)...)
110	
111		case MigrateRemoveAction:
112			if sql.IsSqlite() {
113				return nil
114			}
115	
116			return []string{fmt.Sprintf(sql.AlterTableDropColumnStm(), sql.EscapeSqlName(tbName), sql.EscapeSqlName(c.Name))}
117	
118		case MigrateModifyAction:
119			def, isPk := c.pkDefinition(false)
120			if isPk {
121				if _, isPrevPk := c.pkDefinition(true); isPrevPk {
122					// avoid repeat define primary key
123					def = strings.Replace(def, " "+sql.PrimaryOption(), "", 1)
124				}
125			}
