	newIdx.Action = MigrateAddAction

	oldTable := NewTableWithAction("tbl", MigrateNoAction)
	oldTable.AddIndex(oldIdx)

	newTable := NewTableWithAction("tbl", MigrateNoAction)
	newTable.AddIndex(newIdx)

